  "Esperando o comando terminar": "Chờ lệnh kết thúc",
  "Está parado num comando no terminal, esperando ele terminar para continuar o turno.": "Anh ấy đang đứng trước cửa ra lệnh ở nhà ga, đợi nó kết thúc để có thể tiếp tục ca làm việc của mình.",
  "Terminou o turno e está esperando {0} shells terminarem. A cada um que termina, o agente recebe o resultado.": "Agent đã kết thúc lượt và đang chờ {0} shell hoàn tất. Mỗi khi một shell chạy xong, agent sẽ nhận kết quả.",
  "Terminou o turno e está esperando o shell terminar. Quando ele terminar, o agente recebe o resultado.": "Agent đã kết thúc lượt và đang chờ shell hoàn tất. Khi shell chạy xong, agent sẽ nhận kết quả.",
  "Comendo pipoca e assistindo ao terminal": "Ăn bỏng ngô và xem nhà ga",
  "Até 3 min: recosta na cadeira com um balde de pipoca e assiste ao terminal como se fosse um filme.": "Tối đa 3 phút: tựa lưng vào ghế với một xô bỏng ngô và xem thiết bị đầu cuối như thể đó là một bộ phim.",
  "A pipoca acabou: girando na cadeira": "Bỏng ngô đã hết: quay tròn trên ghế",
  "De 3 a 10 min: a pipoca acaba; braços cruzados, dedos batendo e, de vez em quando, um giro completo na cadeira.": "Từ 3 đến 10 phút: bắp hết; khoanh tay, gõ ngón tay và thỉnh thoảng xoay tròn hoàn toàn trên ghế.",
  "Já tem teia de aranha na cadeira": "Trên ghế đã có mạng nhện rồi",
  "Depois de 10 min: aparece uma teia de aranha na cadeira (ela cresce depois de 20 min) e escapa um bocejo.": "Sau 10 phút: một mạng nhện xuất hiện trên ghế (nó mọc lên sau 20 phút) và một cái ngáp thoát ra.",
  "Cochilou esperando o shell": "Ngủ gật chờ shell",
  "Depois de 25 min: cochila na mesa, coberto de teia.": "Sau 25 phút: anh ta ngủ trên bàn, phủ đầy mạng nhện.",
  "atalho {0}": "phím tắt {0}",
  "atalhos {0} ou {1}": "phím tắt {0} hoặc {1}",
  "Restaurar o tamanho": "Khôi phục kích thước",
  "Expandir na tela toda": "Mở rộng ra toàn màn hình",
  "Habblaud — precisa de você": "Habblaud - cần bạn",
  "O servidor do Habblaud não responde. Confira se ele está rodando (npm run dev ou npm start); seguimos tentando.": "Máy chủ Habblaud không phản hồi. Kiểm tra xem nó có đang chạy không (npm run dev hoặc npm start); chúng tôi tiếp tục cố gắng.",
  "Não foi possível conectar ao servidor do Habblaud. Tentando de novo…": "Không thể kết nối với máy chủ Habblaud. Đang thử lại...",
  "Ver demonstração": "Xem bản demo",
  "O escritório está vazio": "Văn phòng trống rỗng",
  "Não foi possível ligar a demonstração.": "Không thể bật bản demo.",
  "Tentar agora": "Thử ngay bây giờ",
  "Sem conexão com o servidor do Habblaud há algum tempo. O escritório mostra o último estado conhecido.": "Không có kết nối với máy chủ Habblaud trong một thời gian. Văn phòng hiển thị trạng thái được biết cuối cùng.",
  "O servidor do Habblaud não responde. Confira se ele está rodando (npm run dev ou npm start).": "Máy chủ Habblaud không phản hồi. Kiểm tra xem nó có đang chạy không (npm run dev hoặc npm start).",
  " Tentando reconectar…": "Đang cố gắng kết nối lại...",
  " Nova tentativa em {0} s.": "Thử lại trên {0} s.",
  "só nesta sessão": "chỉ trong phiên này",
  "neste projeto, só para você": "trong dự án này, chỉ dành cho bạn",
  "neste projeto, para todos (versionado)": "trong dự án này, dành cho tất cả mọi người (đã được phiên bản)",
  "em todos os projetos": "trong tất cả các dự án",
  "voltando ao terminal…": "quay trở lại thiết bị đầu cuối…",
  "volta ao terminal em {0} s": "quay trở lại thiết bị đầu cuối tại {0} s",
  "volta ao terminal em menos de 1 min": "quay lại nhà ga sau chưa đầy 1 phút",
  "volta ao terminal em {0}": "quay trở lại thiết bị đầu cuối tại {0}",
  "No Codex, a aprovação só aparece no terminal depois que você responder aqui ou o prazo acabar.": "Trong Codex, phê duyệt chỉ xuất hiện trong thiết bị đầu cuối sau khi bạn phản hồi tại đây hoặc thời hạn đã qua.",
  "Este subagente roda em segundo plano: o terminal só mostra o pedido depois que você responder aqui ou escolher “Responder no terminal”.": "Agent phụ này chạy ở chế độ nền: thiết bị đầu cuối chỉ hiển thị yêu cầu sau khi bạn phản hồi tại đây hoặc chọn “Trả lời trong thiết bị đầu cuối”.",
  "recolher": "thu thập",
  "Aprovado": "Đã được phê duyệt",
  "Recusado": "Từ chối",
  "Respondido": "Đã trả lời",
  "Devolvido ao terminal": "Đã quay lại thiết bị đầu cuối",
  "Para responder por aqui, abra o Habblaud por http://localhost (ou 127.0.0.1). Por enquanto, responda no terminal.": "Để phản hồi tại đây, hãy mở Habblaud bằng http://localhost (hoặc 127.0.0.1). Bây giờ, hãy trả lời trong thiết bị đầu cuối.",
  "✓ Aprovar": "✓ Phê duyệt",
  "✓ Responder": "✓ Trả lời",
  "Perguntas do agente": "Câu hỏi của agent",
  "✕ Recusar…": "✕ Từ chối…",
  "O Habblaud deixa este pedido de lado: vale o que você responder no terminal": "Habblaud bỏ yêu cầu này sang một bên: bất cứ điều gì bạn trả lời trong thiết bị đầu cuối đều có giá trị",
  "Responder no terminal": "Trả lời trong thiết bị đầu cuối",
  "Aprovar agora e não perguntar de novo: {0} ({1})": "Phê duyệt ngay và không hỏi lại: {0} ({1})",
  "Aprovar e não perguntar de novo:": "Phê duyệt và không hỏi lại:",
  "Motivo (opcional, vai para o agente). Ex.: use pnpm em vez de npm": "Lý do (tùy chọn, liên hệ với agent). Ví dụ: sử dụng pnpm thay vì npm",
  "Motivo da recusa (opcional)": "Lý do từ chối (tùy chọn)",
  "Interromper o agente (ele para e espera você)": "Làm gián đoạn agent (anh ta dừng lại và đợi bạn)",
  "Pergunta do agente": "Câu hỏi của agent",
  "Pedido de permissão": "Yêu cầu cấp phép",
  "Perguntas para você": "Câu hỏi dành cho bạn",
  "Pergunta para você": "Câu hỏi dành cho bạn",
  "Pede permissão": "Xin phép",
  " · subagente {0}": "· agent phụ {0}",
  "Aqui ou no terminal: vale a primeira resposta{0}": "Tại đây hoặc trong thiết bị đầu cuối: câu trả lời đầu tiên được tính{0}",
  "Pedido feito às {0}. Sem resposta aqui até {1}, o Codex segue sem a decisão do escritório e pede a aprovação no terminal.": "Đơn hàng được đặt tại {0}. Không có phản hồi nào ở đây cho đến khi {1}, Codex vẫn chưa có quyết định từ văn phòng và yêu cầu phê duyệt tại nhà ga.",
  "Pedido feito às {0}. Sem resposta aqui até {1}, o Habblaud devolve o pedido ao terminal.": "Đơn hàng được đặt tại {0}. Không có phản hồi ở đây cho đến khi {1}, Habblaud trả lại yêu cầu cho thiết bị đầu cuối.",
  "Carregando os detalhes…": "Đang tải chi tiết…",
  "+{0} {1} deste agente na fila": "+{0} {1} của agent này trong hàng đợi",
  "pedido": "đặt hàng",
  "pedidos": "mệnh lệnh",
  "Não responder: o agente segue sem a resposta (com o motivo, se você escrever um)": "Không có phản hồi: agent tiếp tục mà không có phản hồi (với lý do, nếu bạn viết)",
