  "Começa na hora uma sessão do Claude Code em segundo plano no computador, na pasta escolhida; as permissões chegam aqui. Pasta que o Claude Code ainda não conhece abre no app do Claude e espera o Enter lá. Anexos vão para ~/.habblaud/attachments e o pedido leva os caminhos.": "Phiên Claude Code ngay lập tức bắt đầu ở chế độ nền trên máy tính, trong thư mục đã chọn; quyền đến đây. Thư mục mà Claude Code chưa biết, hãy mở nó trong ứng dụng của Claude và đợi Enter ở đó. Tệp đính kèm đi đến ~/.habblaud/attachments và yêu cầu sẽ nhận các đường dẫn.",
