  "Recomendado: instala o mod do Habblaud no Claude Code (2.1.287 ou mais novo), que passa o uso de 5 h e da semana ao vivo. Rode na pasta do Habblaud, no computador onde o Claude Code roda; nas sessões já abertas, `/reload-plugins`.": "Khuyến nghị: cài đặt mod Habblaud trên Claude Code (2.1.287 hoặc mới hơn), có thể sử dụng trực tiếp trong 5 giờ và một tuần. Chạy nó trong thư mục Habblaud, trên máy tính chạy Claude Code; trong các phiên đã mở, `/reload-plugins`.",
