  "Sem instalar nada: rode `/usage` no Claude Code desta conta para atualizar o cache (os números envelhecem até a próxima vez).": "Không cần cài đặt bất cứ thứ gì: chạy `/usage` trên Claude Code của tài khoản này để làm mới bộ nhớ đệm (số này sẽ cũ cho đến lần tiếp theo).",
