  "Você está na lista de espera": "Bạn đang trong danh sách chờ",
  "O acesso é liberado aos poucos, em lotes. Avisamos por e-mail quando chegar a sua vez.": "Quyền truy cập được phát hành từng chút một, theo đợt. Chúng tôi sẽ thông báo cho bạn qua email khi đến lượt bạn.",
  "Enquanto isso, o Habblaud continua normal e nada do escritório é enviado.": "Trong khi đó, Habblaud vẫn bình thường và không có gì từ văn phòng được gửi đi.",
  "Chegou a sua vez: crie o seu personagem e entre na cidade.": "Đến lượt bạn: tạo nhân vật của bạn và vào thành phố.",
  "Novidade: Habblaud World": "Mới: Thế giới Habblaud",
  "Seu escritório agora pode virar um prédio numa cidade online, aceso enquanto os seus agentes trabalham.": "Văn phòng của bạn giờ đây có thể trở thành một tòa nhà trong thành phố trực tuyến, được thắp sáng trong khi các agent của bạn làm việc.",
  "Seu escritório vira um prédio numa cidade em pixel art, aceso enquanto os seus agentes trabalham.": "Văn phòng của bạn trở thành một tòa nhà trong thành phố nghệ thuật pixel, được thắp sáng trong khi các agent của bạn làm việc.",
  "Crie um personagem, ande pela cidade e visite os prédios de outras pessoas.": "Tạo nhân vật, đi dạo quanh thành phố và thăm các tòa nhà của người khác.",
  "Cumprimente quem passa e deixe likes nos prédios, sem chat e sem spam.": "Chào hỏi bất cứ ai đi ngang qua và để lại lượt thích trên các tòa nhà, không trò chuyện và không spam.",
  "Nada é enviado enquanto você não criar a conta. O acesso é liberado aos poucos, por lista de espera.": "Không có gì được gửi cho đến khi bạn tạo tài khoản. Quyền truy cập được giải phóng dần dần, thông qua danh sách chờ.",
