  "Não foi possível gravar {0} ({1}).": "Không thể ghi {0} ({1}).",
  "Uso: npm run codex:bridge [-- opções]\n\nEntrega as mensagens do escritório às sessões do Codex quando o Habblaud roda no Docker (deixe rodando no computador).\n\nOpções:\n  --port <n>   porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --once       faz uma rodada só e sai\n  -h, --help   mostra esta ajuda\n\nBinário do Codex: HABBLAUD_CODEX_BIN ou `codex` do PATH.": "Cách sử dụng: npm run codex:bridge [-- options]\n\nGửi tin nhắn văn phòng tới các phiên Codex khi Habblaud chạy trong Docker (để nó chạy trên máy tính).\n\nTùy chọn:\n  Cổng --port <n> của Habblaud (mặc định: HABBLAUD_PORT hoặc {0})\n  --once thực hiện một lượt và rời đi\n  -h, --help hiển thị trợ giúp này\n\nNhị phân của Codex: HABBLAUD_CODEX_BIN hoặc `codex` của PATH.",
  "--port precisa de um número entre 1 e 65535.": "--port cần số từ 1 đến 65535.",
