  "fora das pastas de projeto conhecidas": "bên ngoài các thư mục dự án đã biết",
  "✗ arquivo de entrega recusado: {0}": "✗ Tệp giao hàng bị từ chối: {0}",
  "Entregando as mensagens do Habblaud (http://127.0.0.1:{0}) às sessões do Codex com {1}, e começando os agentes novos pedidos no escritório. Ctrl+C para parar.": "Gửi tin nhắn từ các phiên Habblaud (http://127.0.0.1:{0}) đến Codex với {1} và nhận các yêu cầu mới của agent tại văn phòng. Ctrl+C để dừng.",
  "Sem o Codex (codex no PATH ou HABBLAUD_CODEX_BIN): só começo os agentes novos pedidos no Habblaud (http://127.0.0.1:{0}). Ctrl+C para parar.": "Không có Codex (codex trong PATH hoặc HABBLAUD_CODEX_BIN): agent chỉ bắt đầu các yêu cầu mới trong Habblaud (http://127.0.0.1:{0}). Ctrl+C để dừng.",
  "Agentes novos rodam em segundo plano com {0} --bg (pasta confiável; senão, no app do Claude).": "Các agent mới chạy trong nền với {0} --bg (thư mục đáng tin cậy; nếu không thì trong ứng dụng của Claude).",
  "Sem o claude no PATH (ou HABBLAUD_CLAUDE_BIN): agentes novos abrem no app do Claude e esperam o Enter.": "Không có Claude trong PATH (hoặc HABBLAUD_CLAUDE_BIN): các agent mới mở trong ứng dụng của Claude và đợi Enter.",
  "Ditado desligado: falta {0}.": "Tắt chính tả: Thiếu {0}.",
  "Ditado: Whisper local ({0}), idiomas {1} detectados sozinhos.": "Đọc chính tả: Ngôn ngữ thì thầm cục bộ ({0}), {1} chỉ được phát hiện.",
  "Habblaud fora do ar em http://127.0.0.1:{0}; tentando de novo a cada {1} s.": "Habblaud không hoạt động trên http://127.0.0.1:{0};, thử lại sau mỗi {1}.",
  "o Habblaud recusou ({0}{1}).": "Habblaud bị từ chối ({0}{1}).",
  "conectado: os agentes do Codex já recebem mensagens pelo escritório.": "đã kết nối: Agent Codex đã nhận được tin nhắn qua văn phòng.",
  "conectado ao Habblaud.": "được kết nối với Habblaud.",
  "[codex-bridge] Erro: {0}": "[cầu codex] Lỗi: {0}",
  "[codex-bridge] Erro inesperado: {0}": "[codex-bridge] Lỗi không mong muốn: {0}",
  "Aguardando resposta no Habblaud…": "Đang chờ phản hồi trên Habblaud…",
  "Uso: npm run codex:<install|uninstall|status> [-- opções]\n\n  install     acrescenta os hooks do Habblaud no hooks.json de cada pasta do Codex (faz backup antes)\n  uninstall   tira os hooks do Habblaud de cada pasta (os outros hooks ficam)\n  status      mostra se os hooks estão lá e se o Habblaud está respondendo\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --conta <id>     só a pasta desta conta (o nome da pasta, ex.: .codex)\n  --port <n>       porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --espera <s>     quanto o Codex espera sua resposta no Habblaud antes de pedir a aprovação no terminal\n                   (padrão: {1} s; entre {2} e {3})\n  --node <caminho> o Node {4}+ que roda os hooks (padrão: o `node` do shell de login, se for {5}+;\n                   senão o primeiro {6}+ entre /opt/homebrew/bin, /usr/local/bin e o deste comando)\n  -h, --help       mostra esta ajuda\n\nPastas: HABBLAUD_CODEX_DIRS (lista separada por vírgula) ou CODEX_HOME e as pastas ~/.codex* do Codex.\nDepois de instalar, abra o Codex e aprove os hooks do Habblaud em /hooks.": "Cách sử dụng: npm run codex:<install|uninstall|status> [-- tùy chọn]\n\n  cài đặt thêm các hook Habblaud vào hooks.json của mỗi thư mục Codex (sao lưu trước)\n  gỡ cài đặt sẽ xóa các móc Habblaud khỏi mỗi thư mục (các móc khác vẫn còn)\n  trạng thái hiển thị xem các móc có ở đó không và liệu Habblaud có phản hồi hay không\n\nTùy chọn:\n  --dry-run hiển thị những gì sẽ thay đổi mà không ghi lại bất cứ điều gì\n  --conta <id> chỉ thư mục cho tài khoản này (tên thư mục, ví dụ: .codex)\n  Cổng --port <n> của Habblaud (mặc định: HABBLAUD_PORT hoặc {0})\n  --espera <s> và Codex đợi phản hồi của bạn trên Habblaud trước khi yêu cầu phê duyệt trên thiết bị đầu cuối\n                   (mặc định: {1} s; giữa {2} và {3})\n  --node <caminho> Nút {4}+ chạy các hook (mặc định: `node` từ shell đăng nhập, nếu là {5}+;\n                   nếu không thì {6}+ đầu tiên giữa /opt/homebrew/bin, /usr/local/bin và lệnh này)\n  -h, --help hiển thị trợ giúp này\n\nCác thư mục: HABBLAUD_CODEX_DIRS (danh sách được phân tách bằng dấu phẩy) hoặc CODEX_HOME và các thư mục ~/.codex* của Codex.\nSau khi cài đặt, hãy mở Codex và phê duyệt các hook Habblaud trong /hooks.",
  "\"hooks\" em formato desconhecido; nada foi alterado": "\"móc\" ở định dạng không xác định; không có gì thay đổi",
  "\"hooks.{0}\" em formato desconhecido; nada foi alterado": "\"hooks.{0}\" ở định dạng không xác định; không có gì thay đổi",
  "já instalado": "đã được cài đặt",
  "instalado em {0}": "được cài đặt trên {0}",
  "instalado ({0} eventos)": "đã cài đặt (sự kiện {0})",
  "atualizado em {0}": "đã cập nhật trên {0}",
