  "Derrubando o container…": "Đập thùng container…",
  "Pronto. Os nomes dos personagens continuam guardados no volume habblaud-data.": "Xong. Tên của các nhân vật vẫn được lưu trữ trong ổ dữ liệu hablaud.",
  "já existe um Habblaud rodando fora do Docker em {0} (npm run dev ou npm start?).\n": "Hiện đã có Habblaud chạy bên ngoài Docker tại {0} (npm run dev hay npm start?).",
  "Pare-o antes, ou use outra porta: HABBLAUD_PORT=4848 npm run docker:up": "Dừng nó trước hoặc sử dụng một cổng khác: HABBLAUD_PORT=4848 npm run docker:up",
  "nenhuma pasta do Claude Code (com projects/ ou sessions/) foi encontrada em ~/.claude*.\n": "không tìm thấy thư mục Claude Code (với dự án/ hoặc phiên/) trong ~/.claude*.",
  "  O escritório vai abrir vazio (dá para ligar o modo demonstração na interface).\n": "Văn phòng sẽ mở trống (bạn có thể bật chế độ demo trong giao diện).",
  "  Se as contas estiverem em outro lugar: HABBLAUD_CLAUDE_DIRS=/caminho/conta1,/caminho/conta2 npm run docker:up": "Nếu các tài khoản ở nơi khác: HABBLAUD_CLAUDE_DIRS=/path/account1,/path/account2 npm run docker:up",
  "Conta {0} ({1}): monta {2} de {3}, somente leitura.": "Tài khoản {0} ({1}): gắn {2} từ {3}, chỉ đọc.",
  "{0} não tem projects/ nem sessions/; conta ignorada.": "{0} không có dự án/hoặc phiên/; tài khoản bị bỏ qua.",
  "{0} é uma pasta do Codex, não do Claude Code; conta ignorada.": "{0} là thư mục của Codex, không phải Claude Code; tài khoản bị bỏ qua.",
  "Codex {0} ({1}): monta {2} de {3}, somente leitura.": "Codex {0} ({1}): gắn {2} từ {3}, chỉ đọc.",
  "{0} ainda não tem thread-writer-locks/: no container, sessão aberta = conversa modificada nos últimos 30 min (rode o docker:up de novo depois de usar o Codex).": "{0} vẫn không có thread-writer-locks/: trong vùng chứa, phiên mở = cuộc hội thoại được sửa đổi trong 30 phút qua (chạy lại docker:up sau khi sử dụng Codex).",
  "Uso ao vivo (mod ou tap de statusline): monta {0} em {1}, somente leitura.": "Sử dụng trực tiếp (mod dòng trạng thái hoặc nhấn): gắn {0} vào {1}, chỉ đọc.",
  "docker-compose.override.yml gerado.": "docker-compose.override.yml được tạo.",
  "Aguardando o Habblaud responder em {0}…": "Đang chờ Habblaud phản hồi {0}…",
  "o Habblaud não respondeu em {0} s. Veja o que aconteceu com: npm run docker:logs": "Habblaud không phản hồi với {0}. Xem điều gì đã xảy ra với: npm run docker:logs",
