  "{0}: o Claude Code registra a versão {1}, não a {2} (o manifesto em mod/ está com outra versão?)": "{0}: Claude Code đăng ký phiên bản {1}, không phải {2} (tệp kê khai có ở dạng mod/với phiên bản khác không?)",
