  "ainda com o nome antigo ({0}); o docker:up não troca sozinho: rode npm run mod:install": "vẫn giữ tên cũ ({0}); docker:up không tự chuyển đổi: chạy npm run mod:install",
  "o mod está instalado, mas o marketplace {0} sumiu; rode npm run mod:install": "bản mod đã được cài đặt, nhưng thị trường {0} đã biến mất; chạy npm chạy mod: cài đặt",
  "o mod vem de outra pasta ({0}), então não foi atualizado; para usar esta: npm run mod:install": "mod đến từ một thư mục khác ({0}), vì vậy nó chưa được cập nhật; để sử dụng cái này: npm run mod:install",
  "marketplace {0}: catálogo relido": "thị trường {0}: đọc lại danh mục",
