  "! nome antigo ainda registrado: {0}; npm run mod:install troca pelo habblaud": "! tên cũ vẫn được đăng ký: {0}; npm run mod: cài đặt giao dịch hoán đổi cho hablaud",
  "! tap de statusline antigo ainda instalado junto com o mod: npm run mod:install tira (ou npm run usage:uninstall)": "! tap dòng trạng thái cũ vẫn được cài đặt cùng với mod: npm run mod:install Strip (hoặc npm run use:uninstall)",
  "tap de statusline antigo instalado (jeito antigo; o mod o substitui)": "Đã cài đặt tap dòng trạng thái cũ (cách cũ; mod thay thế nó)",
  "! hook de permissão antigo ainda no settings.json junto com o plugin: os dois respondem; npm run mod:install tira (ou npm run hooks:uninstall)": "! móc cấp phép cũ vẫn còn trong settings.json cùng với plugin: cả hai đều phản hồi; npm run mod:install dải (hoặc npm run hooks:uninstall)",
  "hook de permissão antigo instalado (jeito antigo; o plugin de permissões o substitui)": "móc cấp phép cũ đã được cài đặt (cách cũ; plugin cấp phép thay thế nó)",
  "! disableAllHooks está ligado no settings.json desta conta: nenhum mod (nem hook) roda": "! vô hiệu hóaAllHooks được bật trong settings.json của tài khoản này: không có mod (cũng như hook) nào chạy",
  "--conta precisa da pasta da conta (ex.: --conta ~/.claude-conta2).": "--conta cần thư mục tài khoản (ví dụ: --conta ~/.claude-conta2).",
  "--claude precisa de um comando ou caminho.": "--claude cần lệnh hoặc đường dẫn.",
  "package.json sem \"version\" em {0}": "pack.json không có \"phiên bản\" trong {0}",
  "não consegui listar os marketplaces ({0})": "Tôi không thể liệt kê các thị trường ({0})",
