  "pelo mod": "theo chế độ",
  "pelo tap de statusline": "bằng cách nhấn vào dòng trạng thái",
  "nenhum uso capturado ainda (chega depois da próxima resposta numa sessão aberta desta conta)": "chưa ghi lại mức sử dụng nào (đến sau phản hồi tiếp theo trong phiên mở của tài khoản này)",
  "Nenhuma conta do Claude Code encontrada (~/.claude* com projects/ ou sessions/). Use --conta <pasta> ou HABBLAUD_CLAUDE_DIRS.": "Không tìm thấy tài khoản Claude Code nào (~/.claude* với dự án/ hoặc phiên/). Sử dụng --conta <pasta> hoặc HABBLAUD_CLAUDE_DIRS.",
  "Não achei {0}: esta pasta não tem o mod (versão antiga do Habblaud? rode git pull).": "Tôi không tìm thấy {0}: thư mục này không có mod (phiên bản cũ của Habblaud? chạy git pull).",
  "Não consegui rodar o Claude Code: {0}.": "Tôi không thể chạy Claude Code: {0}.",
  "Instale o Claude Code (https://code.claude.com) ou diga onde ele está: npm run mod:<comando> -- --claude <caminho>": "Cài đặt Claude Code (https://code.claude.com) hoặc cho chúng tôi biết nó ở đâu: npm run mod:<comando> -- --claude <caminho>",
  "! Não entendi a versão do Claude Code (\"{0}\"); sigo assim mesmo.": "! Tôi không hiểu phiên bản Claude Code (\"{0}\"); Dù sao thì tôi vẫn tiếp tục.",
  "O mod precisa do Claude Code {0} ou mais novo, e este é o {1}.": "Bản mod cần Claude Code {0} hoặc mới hơn và đây là {1}.",
  "Atualize o Claude Code (claude update) e rode de novo. Ou use o jeito antigo, que funciona em versões anteriores:": "Cập nhật Claude Code (cập nhật claude) và chạy lại. Hoặc sử dụng cách cũ, hoạt động trong các phiên bản trước:",
  "  npm run usage:install    # uso de 5h/semanal ao vivo (tap de statusline)": "Cách sử dụng npm run: cài đặt # 5h/tuần sử dụng trực tiếp (nhấn vào dòng trạng thái)",
  "  npm run hooks:install    # responder pedidos de permissão pelo escritório": "npm run hooks:install # trả lời các yêu cầu cấp phép từ văn phòng",
