  "(versão desconhecida)": "(phiên bản không rõ)",
  " — o mod precisa do {0}+": "— mod cần {0}+",
  "✓ pasta do uso criada: {0}": "✓ thư mục sử dụng đã được tạo: {0}",
  "! não consegui criar {0} ({1}); o uso ao vivo não vai ser gravado": "! Tôi không thể tạo {0} ({1}); việc sử dụng trực tiếp sẽ không được ghi lại",
  "    ✗ settings.json: {0}": "✗ settings.json: {0}",
  "  ~ {0} (simulação: claude {1})": "~ {0} (mô phỏng: claude {1})",
  "  ✗ {0}: falhou ({1})": "✗ {0}: không thành công ({1})",
  "  ! nome antigo ainda registrado: {0}; rode npm run mod:install de novo (ou confira com npm run mod:status)": "! tên cũ vẫn được đăng ký: {0}; Chạy lại npm run mod:install (hoặc kiểm tra bằng npm run mod:status)",
  "  ✗ settings.json: {0}; o tap e o hook antigos não foram conferidos": "✗ settings.json: {0}; vòi và móc cũ chưa được kiểm tra",
  "  ! disableAllHooks está ligado no settings.json desta conta: o mod não roda até você desligar": "! vô hiệu hóaAllHooks được bật trong settings.json của tài khoản này: mod không chạy cho đến khi bạn tắt nó",
