  "  ✗ não consegui gravar o settings.json ({0}); o tap e o hook antigos continuam": "✗ Tôi không thể lưu settings.json ({0}); vòi và móc cũ vẫn còn",
  "Pronto. Sessões novas do Claude Code já carregam o mod; nas que já estão abertas, rode /reload-plugins (ou": "Xong. Các phiên mới của Claude Code đã tải mod; đối với những cái đã mở, hãy chạy /reload-plugins (hoặc",
  "reabra a sessão). O uso de 5h/semanal chega ao Habblaud depois da próxima resposta de cada sessão.": "mở lại phiên). Mức sử dụng 5 giờ/tuần đạt Habblaud sau phản hồi tiếp theo của mỗi phiên.",
  "Para conferir: npm run mod:status · Para desfazer: npm run mod:uninstall": "Để kiểm tra: npm run mod:status · Để hoàn tác: npm run mod:uninstall",
  "Pronto. Sessões já abertas continuam com o mod até /reload-plugins (ou até reabrir a sessão).": "Xong. Các phiên đã mở sẽ tiếp tục với bản mod cho đến khi /reload-plugins (hoặc cho đến khi bạn mở lại phiên).",
  "Para voltar ao jeito antigo (Claude Code anterior ao 2.1.287): npm run usage:install e npm run hooks:install": "Để quay lại cách cũ (Claude Code trước 2.1.287): npm run use:install và npm run hooks:install",
  "Habblaud em http://127.0.0.1:{0}": "Habblaud trên http://127.0.0.1:{0}",
  "{0}: fora do ar (o mod segue gravando o uso; os pedidos de permissão ficam só no terminal).": "{0}: ngoại tuyến (mod tiếp tục ghi lại mức sử dụng; yêu cầu cấp phép chỉ có trên thiết bị đầu cuối).",
  "{0}: no ar e respondendo pedidos de permissão (com alguma página aberta).": "{0}: trực tiếp và phản hồi các yêu cầu cấp phép (với một số trang đang mở).",
  "{0}: no ar, mas responder pelo escritório está desligado (porta exposta na rede ou HABBLAUD_TERMINAL=0).": "{0}: đang phát sóng nhưng phản hồi từ văn phòng bị ngắt kết nối (cổng hiển thị trên mạng hoặc HABBLAUD_TERMINAL=0).",
  "Mensagens pelo escritório: ligadas (chegam às sessões abertas com o plugin {0}).": "Tin nhắn xung quanh văn phòng: được kết nối (tiếp cận các phiên mở bằng plugin {0}).",
  "Mensagens pelo escritório: desligadas no Habblaud (porta exposta na rede, HABBLAUD_TERMINAL=0 ou HABBLAUD_MENSAGENS=0).": "Nhắn tin văn phòng: đã tắt trên Habblaud (cổng hiển thị trên mạng, HABBLAUD_TERMINAL=0 hoặc HABBLAUD_MENSAGENS=0).",
  "não consegui consultar o Claude Code ({0}); o mod não foi conferido.": "Tôi không thể truy vấn Claude Code ({0}); mod chưa được kiểm tra.",
