  "[remote-mdns] anunciando {0}.local -> {1}": "[remote-mdns] quảng cáo {0}.local -> {1}",
  "Uso: npm run remote:setup [-- opções]\n\nLiga o acesso pelo celular (https://<nome>.local) com usuário, senha e HTTPS.\n\n  --user <nome>        usuário do login (padrão: o seu usuário do sistema)\n  --name <nome>        endereço <nome>.local (padrão: habblaud)\n  --domain <endereço>  endereço próprio, ex.: meuclaude.home (precisa de uma entrada no DNS do roteador)\n  --port <n>           porta no computador (padrão: 443 se estiver livre, senão 4748)\n  --allow <lista>      o que o celular pode fazer: permissions, messages, terminal, spawn, none (padrão: permissions)\n  --password-stdin     lê a senha da entrada padrão (automação), em vez de perguntar\n  --no-service         não instala o serviço do anúncio <nome>.local (rode npm run remote:mdns você mesmo)\n  --off                desliga o acesso pelo celular (tira as linhas do .env e o serviço; mantém a CA)": "Cách sử dụng: npm run remote:setup [-- options]\n\nKết nối truy cập qua điện thoại di động (https://<nome>.local) với tên người dùng, mật khẩu và HTTPS.\n\n  Người dùng đăng nhập --user <nome> (mặc định: người dùng hệ thống của bạn)\n  Địa chỉ --name <nome> <nome>.local (mặc định: habblaud)\n  Địa chỉ riêng của --domain <endereço>, ví dụ: meuclaude.home (cần mục nhập DNS trên bộ định tuyến)\n  Cổng --port <n> trên máy tính (mặc định: 443 nếu rảnh, nếu không thì 4748)\n  --allow <lista> những gì điện thoại di động có thể làm: quyền, tin nhắn, thiết bị đầu cuối, sinh sản, không có (mặc định: quyền)\n  --password-stdin đọc mật khẩu từ đầu vào tiêu chuẩn (tự động hóa) thay vì hỏi\n  --no-service không cài đặt dịch vụ từ quảng cáo <nome>.local (tự chạy npm run remote:mdns)\n  --off tắt quyền truy cập điện thoại di động (xóa dòng .env và dịch vụ; giữ CA)",
