  " CA local nova (o endereço mudou ou a anterior não tinha restrição de nomes): instale o certificado de novo no celular.": "CA cục bộ mới (địa chỉ đã thay đổi hoặc địa chỉ trước đó không có hạn chế về tên): cài đặt lại chứng chỉ trên điện thoại di động.",
