  "  Primeira vez: aceite o aviso, toque em \"Instale o certificado do Habblaud\" e confie nele": "Lần đầu tiên: Chấp nhận cảnh báo, nhấn \"Cài đặt chứng chỉ cho Habblaud\" và tin tưởng nó",
  "    iPhone:  Ajustes > Perfil Baixado > Instalar; depois Ajustes > Geral > Sobre > Ajustes de Confiança de Certificados": "iPhone: Cài đặt > Hồ sơ đã tải xuống > Cài đặt; sau đó Cài đặt > Chung > Giới thiệu > Cài đặt tin cậy chứng chỉ",
  "    Android: Configurações > Segurança > Criptografia e credenciais > Instalar certificado > Certificado de CA": "Android: Cài đặt > Bảo mật > Mã hóa và thông tin xác thực > Cài đặt chứng chỉ > Chứng chỉ CA",
  "  Impressão digital da CA (confira no celular antes de confiar):": "Dấu vân tay CA (kiểm tra trên điện thoại di động của bạn trước khi tin tưởng):",
  "(indisponível)": "(không có sẵn)",
  "[remote-setup] Erro: {0}": "[thiết lập từ xa] Lỗi: {0}",
  "Uso: npm run usage:<install|uninstall|status> [-- opções]\n\n  install     envolve o statusline de cada conta com o tap do Habblaud (faz backup do settings.json)\n  uninstall   restaura o statusline original de cada conta\n  status      mostra se o tap está instalado e quando chegou o último uso de cada conta\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no statusline (padrão: detectado no PATH)\n  -h, --help       mostra esta ajuda\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS). Uso capturado em HABBLAUD_USAGE_DIR (padrão ~/.habblaud/usage).": "Cách sử dụng: cách sử dụng npm run: <install|uninstall|status> [-- tùy chọn]\n\n  cài đặt sẽ kết thúc dòng trạng thái của từng tài khoản bằng thao tác nhấn Habblaud (sao lưu settings.json)\n  gỡ cài đặt khôi phục dòng trạng thái ban đầu của mỗi tài khoản\n  trạng thái hiển thị xem vòi đã được cài đặt chưa và thời điểm sử dụng lần cuối của từng tài khoản\n\nTùy chọn:\n  --dry-run hiển thị những gì sẽ thay đổi mà không ghi lại bất cứ điều gì\n  Lệnh nút --node <cmd> được sử dụng trong dòng trạng thái (mặc định: được phát hiện trong PATH)\n  -h, --help hiển thị trợ giúp này\n\nTài khoản: giống như máy chủ (~/.claude* với dự án/ hoặc phiên/, CLAUDE_CONFIG_DIR hoặc\nHABBLAUD_CLAUDE_DIRS). Mức sử dụng được ghi lại trong HABBLAUD_USAGE_DIR (mặc định ~/.habblaud/usage).",
